"""Application sans état — lot 5 (UI Shiny, posture D-0007/D-0008).

L'application du MVP (stratégie §2.3/§4.6) : le syndic ouvre le dossier de
copropriété (ZIP, exemplaire maître D-0013), travaille, « Enregistrer »
télécharge une révision complète du dossier. Elle ne garde RIEN : ni
compte, ni secret, ni base de données — les données ne quittent jamais
le poste (D-0007). Le même code tourne en Shinylive (navigateur, livraison
principale D-0008 — export au lot suivant) et en repli serveur
(``shiny run app/``) : l'UI n'utilise pas le module ``js`` ; la sauvegarde
automatique passe par des messages custom Shiny + un script client
embarqué, identiques dans les deux modes.

Architecture (plan lot 5 §C) : ce module ne fait que lier Shiny — toute
la logique vit dans les modules purs ``pdf_appel.py`` (PDF fidèle ODS)
et ``revision.py`` (périodes, saisies journalisées, émission, envois,
révision du dossier), consommés avec ``core/`` (lot 3) et ``dossier/``
(lot 4) sans réouverture (seule extension approuvée : fix F, D-0035).

Assistant 5 étapes calqué sur l'ODS : période → factures → relevés d'eau
→ contrôle (récapitulatif FACTURES, sommes vérifiées) → émission (7 PDF
+ ZIP + envois semi-manuels D-0001). Sauvegarde automatique : la copie de
travail = la révision complète du dossier, stockée côté client
(IndexedDB, plan §E) ; alerte avant fermeture sans enregistrement.
"""
# This file is part of loftRv2 — lot 5 (application sans état).

import base64
import sys
import time
from datetime import datetime, timezone
from pathlib import Path

ICI = Path(__file__).resolve().parent
RACINE = ICI.parent
for _chemin in (str(RACINE), str(ICI)):
    if _chemin not in sys.path:  # pragma: no cover - amorçage shiny run
        sys.path.insert(0, _chemin)

from shiny import App, reactive, render, ui  # noqa: E402

import core  # noqa: E402 — noyau lot 3
import pdf_appel  # noqa: E402
import revision  # noqa: E402

# ---------------------------------------------------------------------------
# Constantes d'affichage (aucune donnée réelle, D-0002)
# ---------------------------------------------------------------------------

TYPES_CHARGE = [t.value for t in core.TypeCharge]
MODES = [m.value for m in core.ModeRepartition]
MODE_DEFAUT = "défaut (règle du type, D-0016)"
MOTIFS_CREDIT = [m.value for m in core.MotifCredit]
MOYENS = [m.value for m in core.MoyenPaiement]
LOTS = ["F1", "F2", "F3", "F4", "F5", "F6", "F7"]

DEBOUNCE_SAUVEGARDE = 5.0
"""Débounce de la sauvegarde automatique (secondes, plan §E)."""

STYLES = """
.badge { display:inline-block; padding:2px 8px; border-radius:10px;
         font-size:0.85em; font-weight:600; }
.b-brouillon { background:#fff3cd; color:#664d03; }
.b-emis { background:#d1e7dd; color:#0f5132; }
.b-fige { background:#e2e3e5; color:#41464b; }
.b-ok { background:#d1e7dd; color:#0f5132; }
.b-err { background:#f8d7da; color:#842029; }
table.loft { border-collapse:collapse; margin:0.4em 0; font-size:0.9em; }
table.loft th, table.loft td { border:1px solid #ccc; padding:3px 7px;
                               text-align:right; }
table.loft td.lib, table.loft th.lib { text-align:left; }
"""

# Script client : sauvegarde automatique (IndexedDB, plan §E — le dossier
# réel dépasse le quota localStorage, plan §B) + alerte avant fermeture.
# Fonctionne à l'identique en Shinylive (iframe same-origin) et en repli
# serveur — messages custom Shiny dans les deux modes.
SCRIPT_CLIENT = r"""
(function () {
  const NOM_BASE = "loftRv2-travail", MAGASIN = "copies", CLE = "travail";
  let base = null, alerteArmee = false, nonce = 0;
  function ouvrir() {
    return new Promise((res, rej) => {
      const r = indexedDB.open(NOM_BASE, 1);
      r.onupgradeneeded = () => r.result.createObjectStore(MAGASIN);
      r.onsuccess = () => res(r.result);
      r.onerror = () => rej(r.error);
    });
  }
  function magasiner(mode, cle, valeur) {
    return new Promise(async (res, rej) => {
      try {
        const d = base || (base = await ouvrir());
        const t = d.transaction(MAGASIN, mode).objectStore(MAGASIN);
        const q = valeur !== undefined ? t.put(valeur, cle) : t.get(cle);
        q.onsuccess = () => res(q.result);
        q.onerror = () => rej(q.error);
      } catch (e) { rej(e); }
    });
  }
  function effacer() {
    return new Promise(async (res, rej) => {
      try {
        const d = base || (base = await ouvrir());
        const q = d.transaction(MAGASIN, "readwrite")
          .objectStore(MAGASIN).delete(CLE);
        q.onsuccess = () => res(true);
        q.onerror = () => rej(q.error);
      } catch (e) { rej(e); }
    });
  }
  function avertir(e) { e.preventDefault(); e.returnValue = ""; }
  function armer(b) {
    if (b && !alerteArmee) window.addEventListener("beforeunload", avertir);
    if (!b && alerteArmee)
      window.removeEventListener("beforeunload", avertir);
    alerteArmee = b;
    window.__loftAlerteArmee = b;
  }
  Shiny.addCustomMessageHandler("loft-copie", async (m) => {
    try {
      if (m.action === "ecrire") {
        await magasiner("readwrite", CLE,
          { horodatage: m.horodatage, b64: m.b64 });
        Shiny.setInputValue("loft_stockage_ok", true);
      } else if (m.action === "effacer") {
        await effacer();
      } else if (m.action === "lire") {
        const v = await magasiner("readonly", CLE);
        Shiny.setInputValue("copie_travail_contenu",
          { b64: v ? v.b64 : null, n: ++nonce });
      }
    } catch (e) { Shiny.setInputValue("loft_stockage_ok", false); }
  });
  Shiny.addCustomMessageHandler("loft-alerte", (m) => armer(!!m.armee));
  (async () => {
    try {
      const v = await magasiner("readonly", CLE);
      if (v) Shiny.setInputValue("copie_travail_presente",
        { horodatage: v.horodatage });
    } catch (e) { /* la bannière d'état signalera l'indisponibilité */ }
  })();
})();
"""


def badge(etat: str) -> str:
    return f'<span class="badge b-{etat}">{etat}</span>'


def _rappel(message: str) -> ui.Tag:
    return ui.p({"style": "color:#888;"}, message)


# ---------------------------------------------------------------------------
# Interface
# ---------------------------------------------------------------------------


def _etape(titre: str, *contenus) -> ui.Tag:
    return ui.card(ui.card_header(titre), *contenus)


app_ui = ui.page_fluid(
    ui.tags.head(ui.tags.style(STYLES)),
    ui.tags.header(
        {"style": "display:flex; flex-wrap:wrap; gap:1em; align-items:end; "
                  "padding:0.6em 0;"},
        ui.h3({"style": "margin:0;"}, "Appel de fonds — copropriété"),
        ui.input_text("initiales", "Vos initiales", value="", width="110px",
                      placeholder="AB"),
        ui.div({"style": "flex:1;"}, ui.output_ui("temoin_sauvegarde")),
        ui.download_button("enregistrer",
                           "Enregistrer (révision du dossier)"),
    ),
    ui.card(
        ui.input_file(
            "dossier_zip", "Ouvrir le dossier de copropriété (ZIP, "
            "exemplaire maître D-0013) :", accept=".zip",
            button_label="Choisir le dossier…"),
        ui.output_ui("etat_dossier"),
        ui.output_ui("banniere_copie"),
    ),
    ui.navset_tab(
        ui.nav_panel(
            "Assistant",
            _etape(
                "Étape 1 — Période",
                ui.output_ui("liste_periodes"),
                ui.layout_columns(
                    ui.input_select("periode_choisie", "Ouvrir une période",
                                    choices=[]),
                    ui.input_action_button("ouvrir_periode",
                                           "Ouvrir la période"),
                    col_widths=(8, 4),
                ),
                ui.layout_columns(
                    ui.input_numeric("exercice", "Exercice", value=2100),
                    ui.input_select("semestre", "Semestre",
                                    choices={"1": "S1", "2": "S2"}),
                    ui.input_action_button("creer_periode",
                                           "Créer la période"),
                    col_widths=(4, 4, 4),
                ),
                ui.output_ui("periode_courante"),
            ),
            _etape(
                "Étape 2 — Factures",
                ui.output_ui("periode_active_rappel"),
                ui.layout_columns(
                    ui.input_text("fact_fournisseur", "Fournisseur"),
                    ui.input_select("fact_type", "Type de charge",
                                    choices=TYPES_CHARGE),
                    ui.input_text("fact_detail", "Détail"),
                    col_widths=(4, 8),
                ),
                ui.layout_columns(
                    ui.input_text("fact_montant", "Montant (€)",
                                  placeholder="1234,56"),
                    ui.input_select("fact_mode", "Mode de répartition",
                                    choices=[MODE_DEFAUT] + MODES),
                    ui.input_text("fact_date", "Date (obligatoire, D-0025)",
                                  placeholder="2100-03-15"),
                    col_widths=(4, 4, 4),
                ),
                ui.input_action_button("ajouter_facture",
                                       "Ajouter la facture"),
                ui.output_ui("table_factures"),
            ),
            _etape(
                "Étape 3 — Relevés d'eau",
                ui.layout_columns(
                    ui.input_text("date_releve",
                                  "Date du relevé (obligatoire)",
                                  placeholder="2100-06-30"),
                    ui.input_action_button("enregistrer_date_releve",
                                           "Enregistrer la date"),
                    col_widths=(8, 4),
                ),
                ui.output_ui("date_releve_affichage"),
                # lignes statiques (jamais re-rendues : la saisie en cours
                # survit aux mises à jour de l'interface — sauvegarde auto
                # comprise) ; le statut de chaque lot vit à part.
                *[
                    ui.layout_columns(
                        ui.div(ui.strong(lot),
                               ui.output_ui(f"releve_statut_{lot}")),
                        ui.input_text(f"compteur_{lot}", "Compteur",
                                      width="110px"),
                        ui.input_text(f"ancien_{lot}", "Ancien index",
                                      width="110px"),
                        ui.input_text(f"nouvel_{lot}", "Nouvel index",
                                      width="110px"),
                        ui.input_checkbox(f"remplacement_{lot}",
                                          "Remplacement (D-0017)"),
                        ui.input_action_button(f"releve_{lot}",
                                               "Enregistrer"),
                        col_widths=(2, 2, 2, 2, 2, 2),
                    )
                    for lot in LOTS
                ],
            ),
            _etape(
                "Étape 4 — Contrôle",
                ui.output_ui("controle"),
            ),
            _etape(
                "Étape 5 — Émission",
                ui.output_ui("periode_active_rappel2"),
                ui.input_action_button("emettre", "Émettre l'appel"),
                ui.output_ui("emission"),
                ui.p("Après émission, téléchargez la révision complète du "
                     "dossier avec « Enregistrer » (bandeau) — c'est ce "
                     "ZIP qui devient l'exemplaire maître (D-0013)."),
            ),
        ),
        ui.nav_panel(
            "Référentiel",
            _etape("Annuaire des lots (F1…Fn — identité pérenne, D-0034)",
                   ui.output_ui("annuaire")),
            _etape(
                "Changement de famille (D-0034 — traçabilité de la "
                "passation)",
                ui.input_select("famille_lot", "Lot", choices=[]),
                ui.input_text_area("nouvelles_coordonnees",
                                   "Nouvelles coordonnées (une ligne par "
                                   "ligne, verbatim)", rows=4),
                ui.input_action_button("changer_famille",
                                       "Remplacer la famille du lot"),
            ),
            _etape(
                "Copropriété (champs réservés, D-0030 — remplis par le "
                "syndic)",
                ui.input_text("copro_nom", "Nom"),
                ui.input_text("copro_adresse", "Adresse"),
                ui.input_text("copro_contact", "Contact du syndic"),
                ui.input_action_button("maj_copropriete",
                                       "Enregistrer la copropriété"),
            ),
        ),
        ui.nav_panel(
            "Suivi (encaissements D-0021, crédits D-0020)",
            _etape(
                "Période suivie",
                ui.input_select("periode_suivi", "Période", choices=[]),
                ui.output_ui("suivi_etat"),
            ),
            _etape(
                "Encaissement (D-0021 — par lot et par appel)",
                ui.layout_columns(
                    ui.input_select("enc_lot", "Lot", choices=[]),
                    ui.input_checkbox("enc_paye", "Payé"),
                    ui.input_text("enc_date", "Date",
                                  placeholder="2100-08-01"),
                    col_widths=(4, 4, 4),
                ),
                ui.layout_columns(
                    ui.input_text("enc_montant", "Montant (€)"),
                    ui.input_select("enc_moyen", "Moyen", choices=MOYENS),
                    ui.input_text("enc_reference", "Référence de paiement"),
                    col_widths=(4, 4, 4),
                ),
                ui.input_action_button("ajouter_encaissement",
                                       "Ajouter l'encaissement"),
            ),
            _etape(
                "Crédit (D-0020 — ajustement signé, motif obligatoire)",
                ui.layout_columns(
                    ui.input_select("cred_lot", "Lot", choices=[]),
                    ui.input_text("cred_montant", "Montant (€, positif)"),
                    ui.input_select("cred_motif", "Motif",
                                    choices=MOTIFS_CREDIT),
                    col_widths=(4, 4, 4),
                ),
                ui.input_text("cred_note", "Note"),
                ui.input_action_button("ajouter_credit", "Ajouter le crédit"),
            ),
            _etape("Figage (D-0018 — l'historique figé est intouchable)",
                   ui.p("Figer verrouille définitivement la période émise : "
                        "plus aucun suivi n'y sera accepté (D-0027)."),
                   ui.input_action_button("figer_periode",
                                          "Figer la période émise suivie")),
            ui.output_ui("suivi_table"),
        ),
    ),
    ui.tags.script(SCRIPT_CLIENT),
)


# ---------------------------------------------------------------------------
# Serveur
# ---------------------------------------------------------------------------


def server(input, output, session):
    class Etat:
        """État de session (posture D : rien ne survit à la session).

        - ``dossier`` : dossier chargé (ses octets portés par lui-même) ;
        - ``periode`` : clé de la période ouverte dans l'assistant ;
        - ``emissions`` : PDF produits en session {clé: {chemin: octets}} ;
        - ``persiste_a`` : longueur du journal au dernier point de
          persistance (chargement, Enregistrer, reprise) — au-delà, il y
          a des mutations non enregistrées (drapeau d'alerte, plan §E) ;
        - ``copie_envoyee_a`` : idem, côté sauvegarde automatique.
        """

        dossier = None
        periode = None
        emissions = {}
        persiste_a = 0
        copie_envoyee_a = 0
        echeance = 0.0
        sauvegarde_ok = None       # None = inconnu, True, False
        copie_presente = None      # {"horodatage"} signalé par le client
        copie_horodatage = None    # dernière copie écrite
        tic_n = 0                  # compteur d'invalidation (non réactif)

    etat = Etat()
    tic = reactive.value(0)
    """``tic`` ne sert qu'à invalider les rendus après chaque changement
    d'état ; sa valeur est portée par un compteur Python ORDINAIRE :
    lire ``tic()`` depuis un effet (pour l'incrémenter) y enregistrerait
    une dépendance réactive et bouclerait l'effet sur lui-même."""

    def _bump():
        etat.tic_n = getattr(etat, "tic_n", 0) + 1
        tic.set(etat.tic_n)

    effacement = reactive.value(False)
    """Demande d'effacement de la copie de travail (après Enregistrer) —
    le téléchargement ne peut pas attendre un message client, la demande
    passe par cet aiguilleur réactif."""

    def _notifier(texte, type_="default"):
        ui.notification_show(texte, type=type_, duration=6)

    def _auteur():
        return revision.exiger_initiales(input.initiales())

    def _sources_fraiches():
        sources = {}
        for par_periode in etat.emissions.values():
            sources.update(par_periode)
        return sources

    def _horodatage_reel():
        return datetime.now(timezone.utc).isoformat(timespec="seconds")

    def _rafraichir_choix():
        if etat.dossier is None:
            return
        cles = sorted(etat.dossier.appels)
        par_etat = {cle: etat.dossier.appels[cle].etat.value
                    for cle in cles}
        libelles = {cle: f"{cle} ({par_etat[cle]})" for cle in cles}
        ui.update_select("periode_choisie", choices=libelles)
        ui.update_select("periode_suivi", choices=libelles)
        familles = etat.dossier.donnees["familles"]
        ui.update_select(
            "famille_lot",
            choices={f["identifiant"]:
                     f"{f['identifiant']} — "
                     f"{f.get('feuille') or '(feuille inconnue)'}"
                     for f in familles})
        lots = [f["identifiant"] for f in familles]
        ui.update_select("enc_lot", choices=lots)
        ui.update_select("cred_lot", choices=lots)
        copro = etat.dossier.donnees.get("copropriete") or {}
        ui.update_text("copro_nom", value=copro.get("nom") or "")
        ui.update_text("copro_adresse", value=copro.get("adresse") or "")
        ui.update_text("copro_contact", value=copro.get("contact") or "")

    # -- chargement du dossier (upload, D-0007) --------------------------

    @reactive.Effect
    def _au_chargement():
        fichier = input.dossier_zip()
        if not fichier:
            return
        with open(fichier[0]["datapath"], "rb") as flux:
            octets = flux.read()
        try:
            dossier = revision.charger_octets(octets)
        except Exception as exc:  # dossier refusé : rien n'est retenu
            message = getattr(exc, "message", str(exc))
            etat.dossier = None
            etat.periode = None
            _notifier(f"Dossier refusé : {message}", "error")
            _bump()
            return
        etat.dossier = dossier
        revision.brancher_horloge(etat.dossier, _horodatage_reel)
        etat.periode = None
        etat.emissions = {}
        etat.persiste_a = len(etat.dossier.journal)
        etat.copie_envoyee_a = etat.persiste_a
        _rafraichir_choix()
        _maj_tous_releves()
        _notifier("Dossier ouvert — "
                  + str(len(etat.dossier.appels)) + " période(s), journal "
                  + str(len(etat.dossier.journal))
                  + " entrées (chaîne et empreinte de tête vérifiées).")
        _bump()

    # -- sauvegarde automatique (copie de travail, plan §E) ---------------

    @reactive.Effect
    async def _sauvegarde_auto():
        reactive.invalidate_later(1.0)
        if etat.dossier is None:
            return
        journal = etat.dossier.journal
        if len(journal) <= etat.copie_envoyee_a:
            return
        if time.time() < etat.echeance:
            return
        try:
            octets = revision.octets_revision(etat.dossier,
                                              _sources_fraiches())
            horodatage = _horodatage_reel()
            await session.send_custom_message(
                "loft-copie",
                {"action": "ecrire", "horodatage": horodatage,
                 "b64": base64.b64encode(octets).decode("ascii")})
            etat.copie_envoyee_a = len(journal)
            etat.sauvegarde_ok = True
            etat.copie_horodatage = horodatage
            _bump()
        except Exception:
            etat.sauvegarde_ok = False
            _bump()

    # -- alerte avant fermeture (armée sur mutations non enregistrées) ---

    _derniere_alerte = {"armee": None}

    @reactive.Effect
    async def _alerte_client():
        tic()
        armee = (etat.dossier is not None
                 and len(etat.dossier.journal) > etat.persiste_a)
        if armee != _derniere_alerte["armee"]:
            _derniere_alerte["armee"] = armee
            await session.send_custom_message("loft-alerte",
                                             {"armee": armee})

    @reactive.Effect
    async def _effacer_copie():
        if effacement():
            await session.send_custom_message("loft-copie",
                                              {"action": "effacer"})
            effacement.set(False)

    # -- copie de travail existante (reprendre / jeter, plan §E) ----------

    @reactive.Effect
    def _copie_presente():
        info = input.copie_travail_presente()
        if info:
            etat.copie_presente = info
            _bump()

    @reactive.Effect
    @reactive.event(input.reprendre_copie)
    async def _reprendre_copie():
        await session.send_custom_message("loft-copie", {"action": "lire"})

    @reactive.Effect
    def _copie_contenu():
        valeur = input.copie_travail_contenu()
        if not valeur or not valeur.get("b64"):
            return
        try:
            octets = base64.b64decode(valeur["b64"])
            dossier = revision.charger_octets(octets)
        except Exception as exc:
            _notifier(f"Copie de travail illisible : "
                      f"{getattr(exc, 'message', exc)}", "error")
            return
        etat.dossier = dossier
        revision.brancher_horloge(etat.dossier, _horodatage_reel)
        etat.emissions = {}
        etat.copie_presente = None
        etat.periode = None
        etat.persiste_a = len(etat.dossier.journal)
        etat.copie_envoyee_a = etat.persiste_a
        _rafraichir_choix()
        _maj_tous_releves()
        _notifier("Copie de travail reprise — les saisies en cours sont "
                  "retrouvées (sauvegarde automatique, plan §E).")
        _bump()

    @reactive.Effect
    @reactive.event(input.jeter_copie)
    async def _jeter_copie():
        etat.copie_presente = None
        await session.send_custom_message("loft-copie",
                                          {"action": "effacer"})
        _notifier("Copie de travail jetée.")
        _bump()

    @reactive.Effect
    def _stockage():
        if input.loft_stockage_ok() is False:
            if etat.sauvegarde_ok is not False:
                etat.sauvegarde_ok = False
                _bump()

    # -- étape 1 : périodes ----------------------------------------------

    @reactive.Effect
    @reactive.event(input.creer_periode)
    def _creer():
        if etat.dossier is None:
            _notifier("Ouvrez d'abord le dossier.", "error")
            return
        try:
            auteur = _auteur()
            cle = revision.creer_periode(
                etat.dossier, int(input.exercice()), int(input.semestre()),
                auteur)
        except (core.ErreurValidation, ValueError, TypeError) as exc:
            _notifier(getattr(exc, "message", str(exc)), "error")
            return
        etat.periode = cle
        _maj_tous_releves()
        _bump()
        _notifier(f"Période {cle} créée (brouillon) — création "
                  f"journalisée par {auteur} (D-0019).")

    @reactive.Effect
    @reactive.event(input.ouvrir_periode)
    def _ouvrir():
        if etat.dossier is None:
            _notifier("Ouvrez d'abord le dossier.", "error")
            return
        cle = input.periode_choisie()
        if not cle:
            return
        etat.periode = cle
        _maj_tous_releves()
        _bump()
        _notifier(f"Période {cle} ouverte "
                  f"({etat.dossier.appels[cle].etat.value}).")

    # -- étape 2 : factures ----------------------------------------------

    @reactive.Effect
    @reactive.event(input.ajouter_facture)
    def _ajouter_facture():
        if etat.dossier is None or etat.periode is None:
            _notifier("Ouvrez (ou créez) d'abord une période (étape 1).",
                      "error")
            return
        try:
            auteur = _auteur()
            mode = None
            if input.fact_mode() != MODE_DEFAUT:
                mode = core.ModeRepartition.de_libelle(input.fact_mode())
            montant = input.fact_montant()
            identifiant = revision.ajouter_facture(
                etat.dossier, etat.periode,
                {"type_charge": core.TypeCharge.de_libelle(
                    input.fact_type()),
                 "montant": montant,
                 "fournisseur": input.fact_fournisseur(),
                 "detail": input.fact_detail(),
                 "date_facture": input.fact_date(),
                 "mode": mode},
                auteur)
        except core.ErreurValidation as exc:
            _notifier(exc.message, "error")
            return
        _bump()
        _notifier(f"Facture {identifiant} ajoutée ({montant} €) — "
                  "journalisée (date exigée par l'UI, D-0025).")

    # -- étape 3 : relevés d'eau ------------------------------------------

    @reactive.Effect
    @reactive.event(input.enregistrer_date_releve)
    def _dater_releve():
        if etat.dossier is None or etat.periode is None:
            _notifier("Ouvrez (ou créez) d'abord une période (étape 1).",
                      "error")
            return
        try:
            revision.definir_date_releve(etat.dossier, etat.periode,
                                         input.date_releve())
        except core.ErreurValidation as exc:
            _notifier(exc.message, "error")
            return
        _bump()
        _notifier("Date du relevé enregistrée.")

    def _maj_releve(lot: str) -> None:
        """Pré-remplit la ligne d'un lot (chaînage : dernier relevé connu,
        étape 3). Ne touche QUE ce lot — la saisie en cours des autres
        lignes n'est jamais écrasée."""
        if etat.dossier is None:
            return
        appel = etat.dossier.appels.get(etat.periode)
        deja = appel.releves.get(lot) if appel is not None else None
        connu = revision.dernier_releve_connu(etat.dossier, lot) or {}
        ui.update_text(
            f"compteur_{lot}",
            value=(deja.compteur if deja is not None
                   else connu.get("compteur")) or "")
        ui.update_text(
            f"ancien_{lot}",
            value=(str(deja.ancien_index) if deja is not None
                   else connu.get("ancien")) or "")
        ui.update_text(
            f"nouvel_{lot}",
            value=str(deja.nouvel_index) if deja is not None else "")
        ui.update_checkbox(f"remplacement_{lot}",
                           value=bool(deja.remplacement)
                           if deja is not None else False)

    def _maj_tous_releves() -> None:
        if etat.dossier is None:
            return
        for f in etat.dossier.donnees["familles"]:
            _maj_releve(f["identifiant"])

    def _fabrique_releve(lot):
        bouton = getattr(input, f"releve_{lot}")

        @reactive.Effect
        @reactive.event(bouton)
        def _saisie():
            if etat.dossier is None or etat.periode is None:
                _notifier("Ouvrez (ou créez) d'abord une période (étape 1).",
                          "error")
                return
            try:
                auteur = _auteur()
                revision.ajouter_releve(
                    etat.dossier, etat.periode, lot,
                    getattr(input, f"compteur_{lot}")(),
                    getattr(input, f"ancien_{lot}")(),
                    getattr(input, f"nouvel_{lot}")(),
                    getattr(input, f"remplacement_{lot}")(),
                    auteur)
            except core.ErreurValidation as exc:
                _notifier(exc.message, "error")
                return
            _maj_releve(lot)  # la ligne reflète le relevé persisté
            _bump()
            _notifier(f"Relevé du lot {lot} journalisé.")
        return _saisie

    def _fabrique_statut_releve(lot):
        def _statut():
            return _statut_releve(lot)

        _statut.__name__ = f"releve_statut_{lot}"
        return render.ui(_statut)

    def _statut_releve(lot):
        tic()
        if etat.dossier is None or etat.periode is None:
            return ui.span({"style": "color:#888; font-size:0.85em;"},
                           "aucune période active")
        appel = etat.dossier.appels[etat.periode]
        deja = appel.releves.get(lot)
        if deja is not None:
            return ui.span(
                {"class": "badge b-emis",
                 "style": "font-size:0.85em;"},
                "relevé déjà saisi — consommation "
                + str(deja.consommation_m3) + " m³")
        connu = revision.dernier_releve_connu(etat.dossier, lot) or {}
        return ui.span(
            {"style": "color:#888; font-size:0.85em;"},
            "chaînage : ancien index du dernier relevé connu"
            if connu.get("ancien") else
            "aucun relevé antérieur — saisissez l'ancien index")

    # -- étape 5 : émission, envois semi-manuels (D-0001) -----------------

    @reactive.Effect
    @reactive.event(input.emettre)
    def _emettre():
        if etat.dossier is None or etat.periode is None:
            _notifier("Ouvrez d'abord une période (étape 1).", "error")
            return
        try:
            auteur = _auteur()
