                                               auteur)
        except (core.ErreurValidation, core.ErreurEtatPeriode) as exc:
            _notifier(getattr(exc, "message", str(exc)), "error")
            return
        etat.emissions[etat.periode] = sources
        _bump()
        _notifier(f"Appel émis — {len(sources)} PDF produits (un par lot, "
                  "nommés identifiant stable + période, D-0034).")

    def _fabrique_envoye(lot):
        bouton = getattr(input, f"envoye_{lot}")

        @reactive.Effect
