    @render.ui
    def controle():
        tic()
        if etat.dossier is None or etat.periode is None:
            return _rappel("Ouvrez une période à l'étape 1.")
        appel = etat.dossier.appels[etat.periode]
        if not appel.factures and not appel.releves:
            return _rappel("Rien à contrôler — saisissez des factures "
                           "(étape 2) et des relevés (étape 3).")
        try:
            resultat = core.calculer_appel(appel)
            erreurs, avertissements = core.valider_appel(appel)
        except core.ErreurValidation as exc:
            return ui.p({"class": "badge b-err"}, exc.message)
        lots = [f.identifiant for f in appel.referentiel.familles]
        tete = ui.tags.tr(
            ui.tags.th({"class": "lib"}, "Facture"),
            ui.tags.th("Montant facturé"),
            ui.tags.th("Montant copropriété"),
            *[ui.tags.th(l) for l in lots])
        corps = []
        for ligne in resultat.lignes:
            corps.append(ui.tags.tr(
                ui.tags.td({"class": "lib"},
                           pdf_appel.libelle_facture(ligne.facture)),
                ui.tags.td(core.euros(ligne.facture.montant_centimes)
                           + " €"),
                ui.tags.td(core.euros(ligne.montant_copro) + " €"),
                *[ui.tags.td(core.euros(ligne.parts[l]) + " €")
                  for l in lots]))
        total_lot = ui.tags.tr(
            ui.tags.td({"class": "lib"}, ui.strong("TOTAL PAR LOFT")),
            ui.tags.td(ui.strong(
                core.euros(resultat.total_facture) + " €")),
            ui.tags.td(ui.strong(
                core.euros(resultat.total_copropriete) + " €")),
            *[ui.tags.td(ui.strong(core.euros(resultat.debit_par_lot[l])
                                   + " €")) for l in lots])
        # invariants du noyau (D-0009) : la somme des parts égale la
        # facture ; le total des débits égale TOTAL FACTURES
        sommes_ok = all(
            sum(ligne.parts.values()) == ligne.facture.montant_centimes
            for ligne in resultat.lignes) and sum(
            resultat.debit_par_lot.values()) == resultat.total_facture
        alertes = [ui.p(
            {"class": "badge b-ok" if sommes_ok else "b-err"},
            "sommes vérifiées — la somme des parts égale la facture, le "
            "total par lot égale TOTAL FACTURES" if sommes_ok else
            "ANOMALIE : invariant rompu (noyau)")]
        for e in erreurs:
            alertes.append(ui.p(
                {"class": "badge b-err"},
                "ERREUR (bloque l'émission) : " + e.message))
        for a in avertissements:
            alertes.append(ui.p(
                {"class": "badge b-brouillon"},
                "Avertissement (arbitrage du syndic, D-0025) : "
                + a.message))
        return [ui.tags.table({"class": "loft"},
                              ui.tags.thead(tete),
                              ui.tags.tbody(*corps),
                              ui.tags.tfoot(total_lot)),
                *alertes]

    @render.ui
    def emission():
        tic()
        if etat.dossier is None or etat.periode is None:
            return _rappel("Ouvrez une période à l'étape 1.")
        appel = etat.dossier.appels[etat.periode]
        if appel.etat is core.EtatAppel.BROUILLON:
            return _rappel("Période en brouillon — contrôlez (étape 4) "
                           "puis émettez : un PDF par lot sera produit, "
                           "nommé par identifiant stable + période "
                           "(D-0034).")
        envois = revision.envois_journalises(etat.dossier, etat.periode)
        copro = etat.dossier.donnees.get("copropriete") or {}
        resultat = core.calculer_appel(appel)
        coordonnees_par_lot = {
            f.get("identifiant"): f.get("coordonnees") or []
            for f in etat.dossier.donnees["familles"]}
        lignes = []
        for f in etat.dossier.donnees["familles"]:
            lot = f["identifiant"]
            solde = resultat.solde_par_lot.get(lot, 0)
            lien = revision.lien_mailto(
                lot, etat.periode, solde, coordonnees_par_lot.get(lot),
                copro.get("contact"))
            envoye = envois.get(lot)
            if envoye:
                statut = ui.span(
                    {"id": f"statut_envoi_{lot}", "class": "badge b-emis"},
                    "marqué envoyé le " + str(envoye[0]) + " par "
                    + str(envoye[1]))
            else:
                statut = ui.span(
                    {"id": f"statut_envoi_{lot}", "class": "badge b-fige"},
                    "non envoyé")
            lignes.append(ui.layout_columns(
                ui.div(ui.strong(lot),
                       ui.div({"style": "font-size:0.85em; color:#666;"},
                              "solde à payer : " + core.euros(solde)
                              + " €")),
                ui.download_button(f"pdf_{lot}", "PDF"),
                ui.a("Message (mailto)", **{
                    "href": lien, "target": "_blank",
                    "class": "btn btn-link"}),
                ui.input_action_button(f"envoye_{lot}", "Marquer envoyé"),
                statut,
                col_widths=(3, 2, 2, 2, 3)))
        return lignes

