REGLE_AUTEUR = re.compile(r"^[A-Z]{2,4}$")
"""Auteur déclaré = initiales, 2 à 4 lettres majuscules (D-0019)."""

JOURS_PAR_MOIS = {1: 31, 2: 28, 3: 31, 4: 30, 5: 31, 6: 30,
                  7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31}


def valider_auteur(auteur: str) -> str:
    """Valide les initiales de l'auteur déclaré (D-0019), sinon erreur."""
    if not isinstance(auteur, str) or not REGLE_AUTEUR.match(auteur):
        raise ErreurValidation(
            f"auteur hors convention (initiales 2-4 majuscules) : {auteur!r}",
            "auteur",
        )
    return auteur


