@dataclass
class Facture:
    """Une facture de charge : montant en centimes, type, mode de
    répartition. ``mode`` explicite (dérogation éventuelle) ou None : la
    facture suit alors la règle par défaut de son type (D-0016).

    Le montant copropriété n'est jamais saisi : il est dérivé des parts
    (plan §4.3). La date est optionnelle : absente ou hors période, elle
    produit un avertissement (D-0025), l'exigence de date étant portée par
    l'UI au lot 5.
    """

    identifiant: str
    type_charge: TypeCharge
    montant_centimes: int
    mode: object = None
    fournisseur: str = ""
    detail: str = ""
    date_facture: date = None

    def __post_init__(self):
        if not self.identifiant or not isinstance(self.identifiant, str):
            raise ErreurValidation(
                f"identifiant de facture requis : {self.identifiant!r}", "facture"
            )
        if not isinstance(self.type_charge, TypeCharge):
            raise ErreurValidation(
                f"type de charge invalide : {self.type_charge!r}", "type_charge"
            )
        if not isinstance(self.montant_centimes, int) or self.montant_centimes <= 0:
            raise ErreurValidation(
                f"montant de facture invalide (centimes > 0 attendu) : "
                f"{self.montant_centimes!r}",
                "montant",
            )
        if self.mode is not None and not isinstance(self.mode, ModeRepartition):
            raise ErreurValidation(
                f"mode de répartition invalide : {self.mode!r}", "mode"
            )
        if self.date_facture is not None and not isinstance(self.date_facture, date):
            raise ErreurValidation(
                f"date de facture invalide : {self.date_facture!r}", "date"
            )

    def mode_effectif(self, referentiel: Referentiel) -> ModeRepartition:
        """Mode appliqué : explicite si dérogation, sinon règle par défaut."""
        if self.mode is not None:
            return self.mode
        return referentiel.mode_defaut(self.type_charge)

    def to_dict(self) -> dict:
        return {
            "identifiant": self.identifiant,
            "type_charge": self.type_charge.value,
            "montant_centimes": self.montant_centimes,
            "mode": self.mode.value if self.mode is not None else None,
            "fournisseur": self.fournisseur,
            "detail": self.detail,
            "date_facture": (
                self.date_facture.isoformat() if self.date_facture else None
            ),
        }

    @classmethod
    def from_dict(cls, data: dict) -> "Facture":
        return cls(
            identifiant=data["identifiant"],
            type_charge=TypeCharge.de_libelle(data["type_charge"]),
            montant_centimes=int(data["montant_centimes"]),
            mode=(
                ModeRepartition.de_libelle(data["mode"])
                if data.get("mode")
                else None
            ),
            fournisseur=data.get("fournisseur", ""),
            detail=data.get("detail", ""),
            date_facture=(
                date.fromisoformat(data["date_facture"])
                if data.get("date_facture")
                else None
            ),
        )


